import re

import pytest

_TITLE_RE = re.compile(
    r"<title>(.*?)</title>",
    re.IGNORECASE | re.DOTALL | re.ASCII,
)


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    Tag names are matched case-insensitively. The opening tag is exactly
    `<title>` (no attributes). The text is returned unchanged, with no
    stripping or entity decoding. Returns "" if there is no opening tag,
    no closing tag after it, or the title is empty. Does no I/O.
    """
    match = _TITLE_RE.search(html)
    if match is None:
        return ""
    return match.group(1)


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title_returns_empty() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<TITLE>Upper</TITLE>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_text_is_not_stripped() -> None:
    assert title_of("<title>  padded \n</title>") == "  padded \n"


def test_multiline_title() -> None:
    assert title_of("<title>line1\nline2</title>") == "line1\nline2"


def test_first_title_wins() -> None:
    assert title_of("<title>one</title><title>two</title>") == "one"


def test_missing_closing_tag() -> None:
    assert title_of("<html><title>unterminated<body></body>") == ""


def test_closing_tag_only() -> None:
    assert title_of("foo</title>") == ""


def test_closing_before_opening_is_ignored() -> None:
    assert title_of("</title><title>real</title>") == "real"


def test_other_markup_inside_is_kept_verbatim() -> None:
    assert title_of("<title>a &amp; b <b>c</b></title>") == "a &amp; b <b>c</b>"


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title>x</title>", "x"),
        ("before<title>y</title>after", "y"),
        ("<title>日本語</title>", "日本語"),
        ("<titles>nope</titles>", ""),
    ],
)
def test_parametrized(html: str, expected: str) -> None:
    assert title_of(html) == expected
